<?php include '../includes/header.php';$u=user();if($u['institution_type']!=='ashram_shala'&&!is_admin()&&!is_sub_officer())exit('Ashram Shala only.');$date=$_GET['date']??today();$it=$u['institution_type'];$code=$u['institution_code'];if(is_admin()||is_sub_officer()){$it=$_GET['institution_type']??'ashram_shala';$code=$_GET['institution_code']??'';}$where="institution_type='ashram_shala'";if($code!=='')$where.=" AND institution_code='".mysqli_real_escape_string($conn,$code)."'";$r=mysqli_query($conn,"SELECT s.*,COALESCE(a.status,'') attendance_status,COALESCE(a.remarks,'') attendance_remarks FROM students s LEFT JOIN student_attendance a ON a.student_id=s.id AND a.attendance_date='".mysqli_real_escape_string($conn,$date)."' WHERE $where AND s.status='active' ORDER BY s.class_name,s.student_name");?>
<div class="page-head"><div><p class="eyebrow">ASHRAM SHALA</p><h1>Daily Student Presenty</h1><p class="muted">Mark present, absent or leave for each student.</p></div></div><div class="card"><form method="post" action="attendance_save.php"><?=csrf_field()?><div class="grid two"><div><label>Date</label><input type="date" name="attendance_date" value="<?=e($date)?>" required></div><?php if(is_admin()||is_sub_officer()):?><div><label>Institution Code</label><input name="institution_code" value="<?=e($code)?>" placeholder="ASHRAM001" required></div><?php else:?><input type="hidden" name="institution_code" value="<?=e($code)?>"><?php endif;?></div><div class="table-wrap"><table><tr><th>Student</th><th>Class</th><th>Status</th><th>Remarks</th></tr><?php while($x=mysqli_fetch_assoc($r)):?><tr><td><b><?=e($x['student_name'])?></b><br><small><?=e($x['student_uid'])?></small><input type="hidden" name="student_ids[]" value="<?=$x['id']?>"></td><td><?=e($x['class_name'])?></td><td><select name="status[<?=$x['id']?>]"><option value="present" <?=$x['attendance_status']==='present'?'selected':''?>>Present</option><option value="absent" <?=$x['attendance_status']==='absent'?'selected':''?>>Absent</option><option value="leave" <?=$x['attendance_status']==='leave'?'selected':''?>>Leave</option></select></td><td><input name="remarks[<?=$x['id']?>]" value="<?=e($x['attendance_remarks'])?>"></td></tr><?php endwhile;?></table></div><button>Save Presenty</button></form></div><?php include '../includes/footer.php';?>
